    parser = argparse.ArgumentParser(description="CLI Calculator")
    parser.add_argument("--op", choices=[
        'add', 'subtract', 'multiply', 'divide', 'power', 'modulo', 
        'memory_store', 'memory_recall', 'memory_clear', 'evaluate', 
        'get_history', 'clear_history'
    ], required=True)
    parser.add_argument("a", type=float, nargs='?', help="First operand or memory value")
    parser.add_argument("b", type=float, nargs='?', help="Second operand")
    parser.add_argument("--expr", type=str, help="Expression string for evaluate")

    args = parser.parse_args()
    calc = Calculator()

    try:
        if args.op in ['add', 'subtract', 'multiply', 'divide', 'power', 'modulo']:
            if args.a is None or args.b is None:
                print("Error: This operation requires two arguments (a and b).")
                return
            result = getattr(calc, args.op)(args.a, args.b)
            print(f"Result: {result}")

        elif args.op == 'memory_store':
            if args.a is None:
                print("Error: memory_store requires a value.")
                return
            calc.memory_store(args.a)
            print("Value stored in memory.")

        elif args.op == 'memory_recall':
            print(f"Memory: {calc.memory_recall()}")

        elif args.op == 'memory_clear':
            calc.memory_clear()
            print("Memory cleared.")

        elif args.op == 'evaluate':
            if not args.expr:
                print("Error: evaluate requires --expr <expression>.")
                return
            print(f"Result: {calc.evaluate(args.expr)}")

        elif args.op == 'get_history':
            print(f"History: {calc.get_history()}")

        elif args.op == 'clear_history':
            calc.clear_history()
            print("History cleared.")

    except ValueError as e:
        print(f"Error: {e}")
    except TypeError as e:
        print(f"Type Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

if __name__ == "__main__":
